public class Escola {
    private String UF;
    private int Área;

    public Escola(String UF, int Área) {
        this.UF = UF;
        this.Área = Área;
    }

    public String getUF() {
        return UF;
    }

    public int getÁrea() {
        return Área;
    }
}

public class Main {
    public static int somaAreasCentroOeste(Escola[] escolas) {
        String[] centroOeste = {"MT", "MS", "GO", "TO"};
        int soma = 0;
        for (Escola escola : escolas) {
            if (Arrays.asList(centroOeste).contains(escola.getUF()) && escola.getÁrea() >= 300) {
                soma += escola.getÁrea();
            }
        }
        return soma;
    }
}
